{
	"Content": "This is a record to be stored in the collection.",
	"Metadata": {
		"source": "manual",
		"category": "example"
	}
}

{
	"Id": "{{indexRecordId}}",
	"Name": "Sample record",
	"Content": "Sample text for Verbex search.",
	"Labels": [
		"sample"
	],
	"Tags": {
		"Source": "Postman"
	},
	"CustomMetadata": {
		"ObjectName": "Sample record"
	}
}

{
	"Documents": [
		{
			"Id": "{{indexRecordId}}-2",
			"Name": "Sample batch record",
			"Content": "Batch sample text.",
			"CustomMetadata": {
				"ObjectName": "Sample batch record"
			}
		}
	]
}

{
	"Prompt": "Respond with a one-sentence smoke test confirmation.",
	"SystemPrompt": "You are a concise and accurate assistant.",
	"MaxTokens": 512,
	"TimeoutMs": 60000
}

{
	"ExternalSearch": {
		"Enabled": false,
		"AllowFallback": true,
		"MaxResults": 10,
		"TimeoutMs": 30000,
		"SafeSearch": true,
		"AllowRawContent": false,
		"IncludeDomains": [],
		"ExcludeDomains": [],
		"Providers": [
			{
				"Name": "default",
				"ProviderType": "Tavily",
				"Endpoint": "https://api.tavily.com/search",
				"ApiKey": "{{tavilyApiKey}}",
				"Enabled": false,
				"IsDefault": true,
				"TimeoutMs": 30000
			}
		]
	}
}

{
	"Name": "My CIFS Crawl",
	"RepositoryType": "CIFS",
	"IngestionSettings": {
		"IngestionRuleId": "rule-guid-here",
		"StoreInS3": true,
		"S3BucketName": "my-bucket"
	},
	"RepositorySettings": {
		"RepositoryType": "CIFS",
		"CifsHostname": "{{cifsHostname}}",
		"CifsUsername": "{{cifsUsername}}",
		"CifsPassword": "{{cifsPassword}}",
		"CifsShareName": "{{cifsShareName}}",
		"IncludeSubdirectories": true
	},
	"Schedule": {
		"IntervalType": "Hours",
		"IntervalValue": 24
	},
	"Filter": {
		"ObjectPrefix": null,
		"ObjectSuffix": null,
		"AllowedContentTypes": null,
		"MinimumSize": 0,
		"MaximumSize": null
	},
	"ProcessAdditions": true,
	"ProcessUpdates": true,
	"ProcessDeletions": false,
	"MaxDrainTasks": 8,
	"RetentionDays": 7
}

{
	"AssistantId": "assistant-guid-here",
	"Category": "general-knowledge",
	"Question": "What is the capital of France?",
	"ExpectedFacts": "[\"Paris is the capital of France\", \"Located in northern France\"]"
}

{
	"AssistantId": "assistant-guid-here",
	"Category": "general-knowledge",
	"Question": "What is the capital of France?",
	"ExpectedFacts": "[\"Paris is the capital of France\", \"Paris is the largest city in France\"]"
}

{
	"messages": [
		{
			"role": "user",
			"content": "What does the document say about revenue?"
		}
	],
	"metadata_filter": {
		"Labels": ["finance"],
		"Tags": ["Q4-2025"]
	}
}

{
	"messages": [
		{
			"role": "user",
			"content": "Give me a summary of this document."
		}
	],
	"attached_document_ids": [
		"{{documentId}}"
	]
}

{
	"messages": [
		{
			"role": "user",
			"content": "Search the assistant collection and answer with the most relevant source details."
		}
	],
	"model": null,
	"temperature": 0.2,
	"max_tokens": 1024
}

{
	"UserMessage": "What is the return policy?",
	"AssistantResponse": "The return policy allows returns within 30 days.",
	"Rating": "ThumbsUp",
	"FeedbackText": "Very helpful response!"
}

{
	"messages": [
		{
			"role": "system",
			"content": "You are a helpful assistant."
		},
		{
			"role": "user",
			"content": "Write a haiku about programming."
		}
	],
	"model": null,
	"temperature": 0.9,
	"max_tokens": 256
}
